const HISTORY={historicalEventId:'goryeo-918',era:'고려',year:918,title:'고려, 새로운 나라의 시작',summary:'918년, 왕건은 궁예를 몰아낸 세력의 추대를 받아 왕위에 올랐습니다. 국호를 고려, 연호를 천수라 정했습니다. 이듬해인 919년에는 철원에서 송악으로 도읍을 옮겼습니다. 936년 후백제를 멸망시키며 후삼국을 통일했습니다.',examKeywords:['918년 고려 건국','왕건(태조)','919년 송악 천도','936년 후삼국 통일'],relatedPeople:['왕건'],relatedQuestions:['q918','q919','q936']};
const QUESTIONS=[{questionId:'q918',examType:'한국사능력검정시험 유형 연습',examRound:null,examYear:null,questionNumber:null,era:'고려',chapterId:'ch01',historicalEventId:'goryeo-918',question:'궁예를 몰아내고 918년에 고려를 세운 인물은 누구일까요?',choices:['견훤','왕건','광종','이성계','궁예'],answer:1,explanation:'왕건은 918년 왕위에 올라 고려를 세웠습니다. 견훤은 후백제를 세웠고, 광종은 고려의 제4대 왕입니다. 이성계는 1392년 조선을 세웠습니다.',source:'살아본 한국사 자체 제작',isOfficial:false,image:null},{questionId:'q919',examType:'한국사능력검정시험 유형 연습',examRound:null,examYear:null,questionNumber:null,era:'고려',chapterId:'ch01',historicalEventId:'goryeo-918',question:'고려 건국 이듬해인 919년에 태조 왕건이 도읍을 옮긴 곳은 어디일까요?',choices:['한양','경주','송악','평양','부여'],answer:2,explanation:'고려는 918년 철원에서 건국되었고, 919년 왕건의 근거지인 송악으로 도읍을 옮겼습니다. 고려 건국(918)과 송악 천도(919)를 구분해 기억하세요.',source:'살아본 한국사 자체 제작',isOfficial:false,image:null},{questionId:'q936',examType:'한국사능력검정시험 유형 연습',examRound:null,examYear:null,questionNumber:null,era:'고려',chapterId:'ch01',historicalEventId:'goryeo-918',question:'다음 사건을 시간순으로 바르게 나열한 것은?\nㄱ. 후삼국 통일  ㄴ. 고려 건국  ㄷ. 송악 천도',choices:['ㄱ → ㄴ → ㄷ','ㄴ → ㄱ → ㄷ','ㄷ → ㄴ → ㄱ','ㄴ → ㄷ → ㄱ','ㄷ → ㄱ → ㄴ'],answer:3,explanation:'고려 건국(918년) → 송악 천도(919년) → 후삼국 통일(936년) 순서입니다. 나라를 세운 것과 후삼국을 통일한 것은 서로 다른 사건입니다.',source:'살아본 한국사 자체 제작',isOfficial:false,image:null}];
