const STORIES={
prologue:{year:2026,location:'서울 · 나의 방',speaker:'나',title:'내일은 꼭 기억하기',dialogue:'책상 위에는 채 식지 않은 커피와 한국사 책이 놓여 있다.\n고려 건국, 918년. 왕건. 송악…\n몇 번이나 읽었는데도, 책을 덮으면 모든 것이 흐릿해진다.',nextStoryId:'sleep'},
sleep:{year:2026,location:'서울 · 늦은 밤',speaker:'나',title:'책장 너머로',dialogue:'“그 시대에 한 번 살아보면, 잊어버리지 않을 텐데.”\n눈꺼풀이 무거워진다. 책장을 넘기던 손이 멈추고, 익숙한 방의 소리가 조금씩 멀어진다.',nextStoryId:'arrival'},
arrival:{year:918,location:'송악 근처 · 낯선 마을',speaker:'나',title:'낯선 아침',dialogue:'거친 서까래 사이로 햇빛이 들어온다.\n휴대폰이 없다. 손목의 시계도, 내가 입었던 옷도.\n밖에서 수레가 덜컹거리는 소리가 들린다.',nextStoryId:'voice'},
voice:{year:918,location:'마을 · 골목',speaker:'마을 사람',title:'이름 하나가 들려왔다',dialogue:'“철원에서 새 임금이 나셨대! 왕건 장군이 왕이 되셨다지 뭔가.”\n왕건…? 교과서에서 보았던 그 이름이다.\n나는 어느 시대에 와 버린 걸까.',nextStoryId:'npc'},
npc:{year:918,location:'마을 · 우물가',speaker:'연화 · 마을 주민',title:'첫 번째 인연',dialogue:'“안색이 좋지 않네요. 길을 잃었어요? 우선 물이라도 마셔요.”\n낯선 여인이 물바가지를 내민다. 지금은 이 사람의 도움이 필요하다.',choices:[choice('물을 받고 고맙다고 한다','market',{health:5},{village:5},'차가운 물 한 모금에 정신이 돌아왔다. 연화는 내 이름을 물으며 미소 지었다.'),choice('여기가 어디인지 먼저 묻는다','market',{knowledge:2},{village:2},'“송악에서 멀지 않은 마을이에요.” 연화가 길을 알려 주었다.')]},
market:{year:918,location:'마을 · 작은 장터',speaker:'나',title:'살아 있는 시대',dialogue:'곡식을 담은 자루, 짚신을 흥정하는 사람들, 아궁이에서 피어오르는 연기.\n책 속의 한 줄이었던 시대가 눈앞에서 숨 쉬고 있다.\n주머니에는 낯선 동전 몇 닢이 들어 있다.',nextStoryId:'rumor'},
rumor:{year:918,location:'마을 · 장터 어귀',speaker:'도윤 · 행상',title:'새 나라의 소문',dialogue:'“송악은 새 임금의 고향이지. 그곳 장터에 가면 소식을 더 들을 수 있을 거야.”\n도윤이 수레 끈을 고쳐 묶는다. 연화는 오늘 마을 창고를 정리해야 한다고 했다.\n어디로 가야 할까?',choices:[choice('송악으로 간다','songak',{wealth:-5,health:-5},{royal:5},'노잣돈을 내고 송악으로 향했다. 새 나라의 소문을 직접 확인하고 싶었다.',{route:'royal',hint:'재산 −5 · 새로운 소식'}),choice('마을에 남는다','village',{health:5},{village:10},'연화를 따라 창고로 향했다. 이곳에서 살아갈 방법부터 찾아보기로 했다.',{route:'village',hint:'체력 +5 · 주민과 인연'}),choice('상인들을 따라간다','merchant',{health:-5},{merchant:10},'도윤의 짐을 함께 싣고 길을 나섰다. 처음 보는 사람이지만 든든한 길동무가 생겼다.',{route:'merchant',hint:'상단 관계 +10'}),choice('기억을 더듬는다','memory',{knowledge:3},{},'918년, 고려 건국. 하지만 송악 천도는 이듬해였다. 책에서 본 문장이 선명해진다.',{hint:'역사 기억 · 지식 +3'})]},
memory:{year:918,location:'마을 · 장터 어귀',speaker:'나 · 역사 기억',title:'아직 오지 않은 내일',dialogue:'왕건이 고려를 세운 곳은 철원. 송악으로 도읍을 옮기는 것은 919년이다.\n미래를 안다는 사실이 이곳에서는 오히려 위험할지도 모른다.\n어떻게 이 기억을 사용할까?',choices:[choice('기억을 감추고 송악의 소식을 살핀다','songak',{knowledge:2,wealth:-5},{royal:5},'앞날을 단정하는 대신 현재의 소식에 귀를 기울였다.',{route:'royal'}),choice('내년에 송악이 도읍이 된다고 말한다','merchant',{fame:-3},{merchant:-3},'“아직 조정에서도 모를 일을 어찌 안다는 거지?” 도윤의 눈에 의심이 스쳤다.',{route:'merchant'}),choice('연화에게 마을 일을 배우기로 한다','village',{health:5},{village:10},'지금 필요한 것은 예언보다 오늘을 살아갈 방법이었다.',{route:'village'})]},
songak:{year:918,location:'송악 · 성문 앞',speaker:'문지기',title:'성문 앞에서',dialogue:'“철원에서 내려온 소식을 들으러 왔나? 장터의 사람들도 온통 그 이야기뿐이야.”\n성문 밖에 한 노인이 짐을 떨어뜨렸다. 줄을 벗어나면 입성이 늦어질 것 같다.',choices:[choice('노인의 짐을 함께 줍는다','royalwork',{health:-5,fame:5},{royal:5},'문지기가 그 모습을 보고 길을 안내해 주었다. 작은 친절이 새로운 인연이 되었다.'),choice('차례를 지키며 사람들의 말을 듣는다','royalwork',{knowledge:3},{royal:2},'사람들은 새 임금의 이름과 바뀐 나라 이름을 몇 번이고 이야기했다.')]},
royalwork:{year:918,location:'송악 · 객사 앞',speaker:'서리',title:'글을 아는 사람',dialogue:'새 소식을 옮겨 적느라 서리가 분주하다.\n“글을 읽을 줄 아나? 이 명단을 정리해 주면 품삯을 주겠네.”\n붓은 낯설지만 사람들의 이름은 읽을 수 있다.',choices:[choice('명단 정리를 돕는다','news',{knowledge:3,wealth:5},{royal:8},'잉크가 손끝에 묻었다. 서리는 다음에도 일손이 필요하면 부르겠다고 했다.',{job:'서리 보조'}),choice('성문 경비의 짐 운반을 돕는다','news',{health:-7,wealth:8,fame:3},{royal:5},'무거운 짐을 나르며 군사들과 말을 텄다. 이곳에서 할 수 있는 일이 생겼다.',{job:'군영 일꾼'})]},
village:{year:918,location:'마을 · 공동 창고',speaker:'연화',title:'작은 마을의 하루',dialogue:'“왕이 바뀌어도 내일 먹을 곡식은 챙겨야 하니까요.”\n비가 들이친 창고에서 곡식 자루를 옮겨야 한다. 한쪽에는 다친 아이가 앉아 있다.',choices:[choice('무거운 곡식 자루를 옮긴다','villagework',{health:-8,wealth:5},{village:8},'등은 뻐근하지만 곡식은 무사했다. 주민들은 내 몫의 식사를 챙겨 주었다.'),choice('아이를 돌보고 쉬게 한다','villagework',{fame:3},{village:10},'아이의 가족이 고마움을 전했다. 연화는 오늘 밤 머무를 방을 내어 주었다.')]},
villagework:{year:918,location:'마을 · 논두렁',speaker:'연화',title:'내가 머물 곳',dialogue:'“며칠 더 머물 거라면 일을 함께해요. 혼자서는 어려워도 같이하면 괜찮아요.”\n이곳에서 처음으로 내일의 약속을 받았다.',choices:[choice('농사일을 배우며 마을에 정착한다','news',{health:-3,wealth:5},{village:7},'땅을 일구는 법부터 배웠다. 낯선 마을에 내 자리가 조금씩 생겼다.',{job:'농민'}),choice('마을 물건을 장터에 내다 판다','news',{wealth:8},{merchant:5,village:3},'주민들의 물건을 대신 팔았다. 세상으로 향하는 길이 조금 더 넓어졌다.',{job:'장터 상인'})]},
merchant:{year:918,location:'송악으로 가는 길',speaker:'도윤',title:'길 위의 동행',dialogue:'“돈보다 중요한 건 신용이야. 한 번 맺은 인연이 먼 길을 열어 주거든.”\n수레 바퀴가 진흙에 빠졌다. 해가 지기 전에 고개를 넘어야 한다.',choices:[choice('힘을 보태 수레를 밀어낸다','merchantwork',{health:-8,wealth:5},{merchant:10},'온몸에 진흙이 묻었지만 수레는 움직였다. 도윤은 품삯과 함께 신뢰를 건넸다.'),choice('주변에서 도움을 구한다','merchantwork',{wealth:-3,fame:3},{merchant:5,village:3},'작은 수고비를 주고 사람들을 모았다. 함께 밀자 수레가 쉽게 빠져나왔다.')]},
merchantwork:{year:918,location:'송악 · 장터',speaker:'도윤',title:'첫 번째 거래',dialogue:'“이 천을 팔아 보겠어? 손님에게 필요한 게 뭔지 먼저 들어 봐.”\n장터의 소음 속에서, 나도 이 시대의 하루를 살아가고 있다.',choices:[choice('값을 낮추고 오랜 거래를 제안한다','news',{wealth:5},{merchant:8},'이익은 작았지만 다음 거래를 약속받았다. 도윤이 고개를 끄덕였다.',{job:'상인'}),choice('품질을 설명하고 제값을 받는다','news',{wealth:10,knowledge:2},{merchant:3},'정성껏 설명한 끝에 첫 거래가 성사되었다. 내 힘으로 번 돈이 손에 남았다.',{job:'상인'})]},
news:{year:918,location:'송악 근처 · 저녁',speaker:'소식을 전하는 사람',title:'새로운 나라, 고려',dialogue:'“새 임금께서 나라 이름을 고려라 하셨다오. 연호는 천수라 하신다지.”\n모여 있던 사람들이 술렁인다. 누군가는 안도하고, 누군가는 또 다른 전란을 걱정한다.\n새 나라의 시작은 모두에게 같은 의미가 아니었다.',nextStoryId:'reflection'},
reflection:{year:918,location:'저녁 · 하루의 끝',speaker:'나',title:'역사의 한 줄 안에서',dialogue:'교과서에는 ‘918년 고려 건국’이라고 적혀 있었다.\n그 한 줄 안에는 연화의 곡식도, 도윤의 수레도, 나의 첫 품삯도 있었다.\n이제 이 사건을 조금은 다르게 기억할 것 같다.',nextStoryId:'promise'},
promise:{year:918,location:'송악 근처 · 밤',speaker:'나',title:'이 시대의 내일',dialogue:'아직 돌아가는 방법은 모른다.\n하지만 내일 만날 사람이 있고, 해야 할 일이 있다.\n오늘의 경험을 잊기 전에 마음속에 새겨 둔다.',choices:[choice('사람들과 맺은 인연을 기억한다','history',{fame:2},{village:2},'낯선 시대에서 나를 버티게 한 것은 사람들이었다.'),choice('새 나라가 시작된 순간을 기억한다','history',{knowledge:3},{royal:2},'왕건, 918년, 고려. 외우던 단어들이 오늘의 장면이 되었다.')]}
};
Object.assign(STORIES,{
desk:{year:2026,location:'서울 · 책상 앞',speaker:'나',title:'같은 이름, 다른 시대',dialogue:'왕건, 견훤, 궁예. 문제 속 이름들이 머릿속에서 뒤섞인다.\n왜 나라가 나뉘었는지, 사람들은 누구를 믿고 살았는지. 연도 옆의 빈칸에는 그런 이야기가 적혀 있지 않다.\n나는 책 귀퉁이에 작은 물음표를 그렸다. 그때 사람들은 내일을 어떻게 기다렸을까?',nextStoryId:'sleep'},
ceiling:{year:918,location:'낯선 집 · 문턱',speaker:'나',title:'문 하나를 사이에 두고',dialogue:'발밑에 놓인 짚신을 신어 본다. 손으로 엮은 끈이 발등을 거칠게 스친다. 창문에는 유리 대신 얇은 종이가 발려 있다.\n꿈이라면 이렇게 생생할 수 있을까.\n문을 밀자 흙냄새와 장작 타는 냄새가 한꺼번에 밀려든다. 골목 끝에서 아이들이 웃으며 달려간다.',nextStoryId:'voice'},
introduction:{year:918,location:'마을 · 우물가',speaker:'연화',title:'이름을 묻는다는 것',dialogue:'“어디서 왔는지는 말하기 어려운가 보네요. 괜찮아요. 이 근처에도 전란을 피해 온 사람이 많거든요.”\n연화는 더 캐묻지 않았다. 돌아갈 곳이 없다는 말이 이 시대에서는 낯설지 않은 모양이다.\n“장터에 가 봐요. 일손을 구하는 사람도 있고, 먼 곳의 소식도 들을 수 있어요.”',nextStoryId:'market'},
grain:{year:918,location:'마을 · 곡식 가게',speaker:'곡식 장수',title:'나라가 바뀌면',dialogue:'“임금이 바뀌었다고 쌀이 저절로 생기는 건 아니지. 올해만큼은 싸움 없이 추수를 했으면 좋겠어.”\n장수는 손바닥에 곡식을 조금 올려 보여 주었다. 작은 낟알들이 햇빛을 받는다.\n누군가에게 새로운 나라는 세력의 변화지만, 이 사람에게는 무사히 수확을 마칠 수 있다는 희망이었다.',nextStoryId:'rumor'},
evening:{year:918,location:'송악 근처 · 해 질 무렵',speaker:'나',title:'처음으로 번 하루',dialogue:'해가 기울자 분주하던 길이 조금씩 조용해진다. 오늘 받은 품삯을 손안에서 굴려 본다. 숫자로만 보이던 돈이 이제 한나절의 노동처럼 느껴진다.\n불과 어젯밤에는 책상 앞에서 정답을 고르고 있었다. 오늘은 무엇을 먹고 어디서 잘지, 누구를 믿어야 할지 선택했다.\n그 선택들이 모여 이곳에서의 내가 되어 간다.',nextStoryId:'news'},
listening:{year:918,location:'마을 · 모닥불 곁',speaker:'연화와 도윤',title:'서로 다른 바람',dialogue:'“길이 안전해지면 더 먼 장터까지 갈 수 있겠지.” 도윤이 말했다.\n연화는 한동안 불꽃을 바라보다 입을 열었다. “나는 떠난 사람들이 돌아왔으면 좋겠어요.”\n나는 대답 대신 고개를 끄덕였다. 고려라는 새 이름 아래에도 사람마다 기다리는 내일은 달랐다.',nextStoryId:'reflection'},
letter:{year:918,location:'잠들기 전 · 작은 방',speaker:'나',title:'미래의 나에게',dialogue:'종이 한 장을 얻어 오늘 있었던 일을 적는다.\n물바가지를 건네준 손. 진흙 묻은 길. 새 나라의 이름을 전하던 목소리.\n언젠가 돌아가 다시 문제를 읽게 된다면, 연도만 떠올리지 않을 것이다. 그날의 냄새와 온도, 사람들의 표정까지 함께 생각날 것이다.',nextStoryId:'promise'}
});
STORIES.prologue.nextStoryId='desk';STORIES.arrival.nextStoryId='ceiling';STORIES.npc.choices.forEach(c=>c.nextStoryId='introduction');STORIES.market.nextStoryId='grain';['royalwork','villagework','merchantwork'].forEach(id=>STORIES[id].choices.forEach(c=>c.nextStoryId='evening'));STORIES.news.nextStoryId='listening';STORIES.reflection.nextStoryId='letter';
Object.entries(STORIES).forEach(([id,s])=>Object.assign(s,{storyId:id,chapterId:'ch01',background:s.year===2026?'seoul-night.png':'goryeo.png',character:s.speaker,characterExpression:'neutral',historicalEventId:'goryeo-918'}));
const INITIAL=()=>({version:1,storyId:'prologue',started:false,completed:false,stats:{health:80,knowledge:10,fame:0,wealth:30},relations:{village:0,merchant:0,royal:0},job:'없음',route:null,visited:[],choices:[],answers:{},wrong:[],reviewed:[],cards:[],pending:null,quizIndex:0,screen:'home',peakWealth:30});
function applyChoice(state,scene,index){const c=STORIES[scene].choices[index];for(const[k,v]of Object.entries(c.statChanges))state.stats[k]=Math.max(0,state.stats[k]+v);for(const[k,v]of Object.entries(c.relationshipChanges))state.relations[k]=Math.max(-100,Math.min(100,state.relations[k]+v));if(c.route)state.route=c.route;if(c.job)state.job=c.job;state.peakWealth=Math.max(state.peakWealth,state.stats.wealth);state.choices.push({scene,label:c.label});state.pending={...c};state.storyId=c.nextStoryId;return state;}


